#include <stdio.h>
#define MAX 5

int queue[MAX];
int front = -1;
int rear = -1;

// Enqueue: Insert element at rear: O(1)
void enqueue(int value) {
    if (rear == MAX - 1) {
        printf("Queue Overflow! Cannot enqueue %d (rear reached MAX-1).\n", value);
        return;
    }
    if (front == -1) {
        front = 0; // First element being inserted
    }
    queue[++rear] = value;
    printf("Enqueued %d (front = %d, rear = %d).\n", value, front, rear);
}

// Dequeue: Remove element from front: O(1)
int dequeue(void) {
    if (front == -1 || front > rear) {
        printf("Queue Underflow! Queue is empty.\n");
        return -1;
    }
    int dequeuedValue = queue[front++];
    printf("Dequeued %d (front = %d, rear = %d).\n", dequeuedValue, front, rear);
    // Reset queue when all elements have been dequeued
    if (front > rear) {
        front = -1;
        rear = -1;
    }
    return dequeuedValue;
}

// Display elements from front to rear: O(n)
void display(void) {
    if (front == -1 || front > rear) {
        printf("Queue is empty.\n");
        return;
    }
    printf("Queue elements: ");
    for (int i = front; i <= rear; i++) {
        printf("%d ", queue[i]);
    }
    printf("\n");
}

int main(void) {
    printf("--- Linear Queue Implementation in C ---\n");
    enqueue(10);
    enqueue(20);
    enqueue(30);
    display(); // 10 20 30

    dequeue(); // Removes 10
    display(); // 20 30

    enqueue(40);
    enqueue(50); // Fills to rear = 4
    display();

    enqueue(60); // Triggers Queue Overflow
    return 0;
}
